// hcMixer is where one mixer's weights sit in the arenas.
type hcMixer struct {
	gamma uint32 // fp32 arena
	down  uint32 // fp16 bank: the fused [lowRank + hc, wide] matrix
	up    uint32 // fp16 bank: the permuted [wide, lowRank] matrix
