		if g.dn, err = NewDeltaNetGPU(dev, dnCfg, g.maxTok, dns); err != nil {
			return fmt.Errorf("llm: deltanet: %w", err)
		}
		mark("deltanet", len(dns), g.dn.Buffers(), g.dn.WeightBytes(), g.dn.ActivationBytes(), start)
	}
	dns = nil
	freeHost()

	start = time.Now()
	var atCfg AttnConfig
	var ats []AttnWeights
	for l := 0; l < g.nLayer; l++ {
		cfg, ok, err := m.AttnConfig(l)
		if err != nil {
			return fmt.Errorf("llm: attn config %d: %w", l, err)
		}
		if !ok {
			continue
		}
		w, err := m.AttnWeights(l)
		if err != nil {
			return fmt.Errorf("llm: attn layer %d: %w", l, err)
		}
		g.kinds[l] = blockKind{attn: true, idx: len(ats)}
		atCfg, ats = cfg, append(ats, w)
	}
	if len(ats) > 0 {
		if g.attn, err = NewAttnGPU(dev, atCfg, g.maxTok, g.nKV, ats); err != nil {
			return fmt.Errorf("llm: attn: %w", err)
		}
		mark("attention", len(ats), g.attn.Buffers(), g.attn.WeightBytes(), g.attn.ActivationBytes(), start)
	}
	ats = nil
	freeHost()

	// 5. The head, before the 77 GB rather than after it: it is 2.54 GB of
	//    host floats in flight a slab at a time, and the bank it fills is the
	//    last dense allocation there is.
	if !opts.NoHead {
		start = time.Now()
		t, err := m.Set.Get("output.weight")
		if err != nil {
			return fmt.Errorf("llm: output.weight: %w", err)
		}
		if g.head, err = NewHeadGPU(dev, c.NEmbd, t, 1); err != nil {
			return fmt.Errorf("llm: head: %w", err)
		}
		mark("lm head", 1, g.head.Buffers(), g.head.WeightBytes(), g.head.ActivationBytes(), start)
		freeHost()
	}

	// 6. The expert banks: 97% of the parameters, staged byte for byte out
	//    of the mmap'd checkpoint, one buffer a layer.
	start = time.Now()
	var moes []MoEWeights
	for l := 0; l < g.nLayer; l++ {
		w, err := m.MoEWeights(l)
		if err != nil {
			return fmt.Errorf("llm: moe layer %d: %w", l, err)
		}
		moes = append(moes, w)
	}
	if g.moe, err = NewMoEGPU(dev, m.MoEConfig(), g.maxTok, moes); err != nil {
		return fmt.Errorf("llm: moe: %w", err)
	}
	mark("moe", len(moes), g.moe.Buffers(), g.moe.WeightBytes(), g.moe.ActivationBytes(), start)
	moes = nil
	freeHost()
	return nil
}

// Layers is how many layers this graph runs, NKV its cache, MaxTokens its
// arenas.
func (g *Graph) Layers() int    { return g.nLayer }
func (g *Graph) NKV() int       { return g.nKV }
func (g *Graph) MaxTokens() int { return g.maxTok }

// Head is the staged output projection, or nil when the graph was built
// without one.
func (g *Graph) Head() *HeadGPU { return g.head }

// Forward runs the whole model over a prompt and returns the logits of its
// last token, which is the only row llama.cpp computes at prefill.
//
// It also returns `result_norm` — the final mixer's output, the tensor the
// head reads — because a logit disagreement has exactly two places to be and
// the caller should not have to run the graph twice to find out which.
func (g *Graph) Forward(ids []int32) (logits, norm []float32, err error) {
	if g.head == nil {
		return nil, nil, fmt.Errorf("llm: this graph was staged without a head")
	}
	norm, err = g.Hidden(ids)
	if err != nil {
		return nil, nil, err
	}
	if err := g.head.Upload(norm, 1); err != nil {
		return nil, nil, err
	}
	if err := g.head.Run(); err != nil {
		return nil, nil, err
	}
	return g.head.Logits(), norm, nil
}

// Hidden runs every layer and the final mixer, and returns `result_norm` for
// the last token: [nEmbd].
func (g *Graph) Hidden(ids []int32) ([]float32, error) {
	nTok := len(ids)
	if nTok <= 0 || nTok > g.maxTok {
		return nil, fmt.Errorf("llm: %d tokens, the arenas are built for %d", nTok, g.maxTok)
	}
	c := g.cfg

	// The embedding gather, and the n-gram one beside it. Both are host-side
	// reads out of the mmap'd checkpoint: `token_embd` is 675 MB of which a
	// prompt touches nTok rows, and the n-gram table is 28.80 GB of which it
	// touches nTok*16 (D2).
	embd, err := g.m.Embeddings(ids)
	if err != nil {
		return nil, fmt.Errorf("llm: token_embd: %w", err)
	}
	var pleEmbd []float32
	if g.hasPLE {
		pleEmbd, err = g.m.PLEGather(PLERows(g.pleCfg, ids), g.pleCfg.NHeads, g.pleCfg.HeadDim)
		if err != nil {
			return nil, fmt.Errorf("llm: per_layer_token_embd: %w", err)
		}
	}

	// The wide residual starts as hc identical copies of the embedding, and
	// from here it lives in the hyper-connection block's arena: every
	// combine updates it in place and nothing else in the graph writes it.
	if err := g.hc.Upload(HCInit(c.HCConfig(), embd, nTok), nTok); err != nil {
		return nil, err
	}
	// A fresh sequence: every DeltaNet layer's recurrent state and the
	// convolution window they share start at zero.
	for l := 0; l < g.nLayer; l++ {
		if k := g.kinds[l]; !k.attn && g.dn != nil {
			if err := g.dn.Reset(k.idx); err != nil {
				return nil, err
			}
		}
	}

	for l := 0; l < g.nLayer; l++ {
		if g.hasPLE && g.pleCfg.IsPLE(l) {
			// The one block that reads and writes the wide residual, so the
			// one place it crosses a boundary. 20.97 MB at 512 tokens, once
			// a graph.
			if err := g.ple.Upload(g.hc.Res(), pleEmbd, nTok); err != nil {
				return nil, err
			}
			if err := g.ple.Run(); err != nil {
				return nil, err
			}
			if err := g.hc.Upload(g.ple.Res(), nTok); err != nil {
				return nil, err
			}
		}

		// The attention half.
		if err := g.hc.Run(2*l, false); err != nil {
			return nil, fmt.Errorf("llm: layer %d attn mix: %w", l, err)
		}
		out, err := g.sublayer(l, g.hc.Mixed(), nTok)
		if err != nil {
			return nil, err
		}
		if err := g.hc.UploadBlockOut(out); err != nil {
			return nil, err
		}
		if err := g.hc.RunCombine(2 * l); err != nil {
			return nil, fmt.Errorf("llm: layer %d attn combine: %w", l, err)
		}

		// The FFN half, which every layer has.
		if err := g.hc.Run(2*l+1, false); err != nil {
			return nil, fmt.Errorf("llm: layer %d ffn mix: %w", l, err)
		}
		if err := g.moe.Upload(g.hc.Mixed(), nTok); err != nil {
			return nil, err
		}
		if err := g.moe.Run(l); err != nil {
			return nil, fmt.Errorf("llm: layer %d moe: %w", l, err)
		}
		if err := g.hc.UploadBlockOut(g.moe.Out()); err != nil {
			return nil, err
		}
		if err := g.hc.RunCombine(2*l + 1); err != nil {
			return nil, fmt.Errorf("llm: layer %d ffn combine: %w", l, err)
		}
	}

	// `inp_out_ids`: everything below is per token, so the reference drops
	// every row but the last before the final mixer. Uploading that one row
	// as a one-token run is the same arithmetic on 1/nTok of the work, and
	// it is what makes `result_norm` comparable against a trace that holds
	// one row.
	wide := c.HCConfig().Wide()
	res := g.hc.Res()
	last := res[(nTok-1)*wide:]
	if err := g.hc.Upload(last, 1); err != nil {
		return nil, err
	}
	if err := g.hc.Run(2*g.nLayer, false); err != nil {
		return nil, fmt.Errorf("llm: head mixer: %w", err)
	}
	return g.hc.Mixed(), nil
}

// sublayer runs one layer's attention half — the gated DeltaNet in 36 layers
// of 48, full attention with the QSA indexer in the other 12 — and returns
// its output, [T][nEmbd].
func (g *Graph) sublayer(l int, mixed []float32, nTok int) ([]float32, error) {
	k := g.kinds[l]
	if k.attn {
		if err := g.attn.Upload(mixed, nTok); err != nil {
			return nil, err
		}
		if err := g.attn.Run(k.idx); err != nil {
			return nil, fmt.Errorf("llm: layer %d attention: %w", l, err)
		}
		return g.attn.Out(), nil
	}
	if err := g.dn.Upload(mixed, nTok); err != nil {
		return nil, err
	}
	if err := g.dn.Run(k.idx); err != nil {
		return nil, fmt.Errorf("llm: layer %d deltanet: %w", l, err)
	}
	return g.dn.Result(), nil
}

// Destroy releases every block.
func (g *Graph) Destroy() {
	for _, d := range []interface{ Destroy() }{g.head, g.moe, g.attn, g.dn, g.ple, g.hc} {
		switch v := d.(type) {
		case *HeadGPU:
			if v != nil {
				v.Destroy()
			}
		case *MoEGPU:
			if v != nil {
				v.Destroy()
			}
		case *AttnGPU:
			if v != nil {
				v.Destroy()
			}
		case *DeltaNetGPU:
			if v != nil {
				v.Destroy()
			}
		case *PLEGPU:
			if v != nil {
				v.Destroy()
			}
		case *HCGPU:
			if v != nil {
				v.Destroy()
			}
		}
	}
}
