package llm

import (
	"testing"
	"time"

	"strix-halo-vulkan/vk"
)

// TestProbeGlue prices the two things the graph's host round trip is made of:
// reading a mapped device arena, and one dispatch submission.
func TestProbeGlue(t *testing.T) {
	dev, done := newTestDevice(t)
	defer done()

	const n = 512 * 2560 // one hc_mixed at llama.cpp's best ubatch
	buf, err := dev.NewBuffer(n * 4)
	if err != nil {
		t.Fatal(err)
	}
	defer buf.Destroy()
	buf.WriteFloat32(make([]float32, n))

	// read back
	start := time.Now()
	const iters = 20
	var sink float32
	for i := 0; i < iters; i++ {
		v := buf.ReadFloat32At(0, n)
		sink += v[0]
	}
	d := time.Since(start) / iters
	t.Logf("read  %6.2f MB from a mapped arena: %8s = %6.2f GB/s (sink %v)",
		float64(n*4)/1e6, d.Round(time.Microsecond), float64(n*4)/d.Seconds()/1e9, sink)

	// write
	src := make([]float32, n)
	start = time.Now()
	for i := 0; i < iters; i++ {
		buf.WriteFloat32At(0, src)
	}
	d = time.Since(start) / iters
	t.Logf("write %6.2f MB into a mapped arena: %8s = %6.2f GB/s",
		float64(n*4)/1e6, d.Round(time.Microsecond), float64(n*4)/d.Seconds()/1e9)

	// plain host memory, for scale
	host := make([]float32, n)
	dst := make([]float32, n)
	start = time.Now()
	for i := 0; i < iters; i++ {
		copy(dst, host)
	}
	d = time.Since(start) / iters
	t.Logf("copy  %6.2f MB host to host:        %8s = %6.2f GB/s",
		float64(n*4)/1e6, d.Round(time.Microsecond), float64(n*4)/d.Seconds()/1e9)

	// one submission, of a trivial dispatch
	m, tr := fixtures(t)
	_ = tr
	w, err := m.HCWeights(0, "attn")
	if err != nil {
		t.Fatal(err)
	}
	g, err := NewHCGPU(dev, m.Config.HCConfig(), 512, []HCWeights{w}, HCOpts{})
	if err != nil {
		t.Fatal(err)
	}
	defer g.Destroy()
	if err := g.Upload(make([]float32, 512*m.Config.HCConfig().Wide()), 512); err != nil {
		t.Fatal(err)
	}
	d3, _, err := g.graph(0, false)
	if err != nil {
		t.Fatal(err)
	}
	for _, name := range []string{"whole (3 dispatches, one submit)", "first alone"} {
		seq := d3
		if name == "first alone" {
			seq = d3[:1]
		}
		var gpu time.Duration
		start = time.Now()
		for i := 0; i < iters; i++ {
			el, err := vk.DispatchMultiTimed(seq, 1, 1, true)
			if err != nil {
				t.Fatal(err)
			}
			gpu += el
		}
		wall := time.Since(start) / iters
		t.Logf("submit %-34s wall %8s, GPU %8s, overhead %8s",
			name, wall.Round(time.Microsecond), (gpu / iters).Round(time.Microsecond),
			(wall - gpu/iters).Round(time.Microsecond))
	}
}
EOF
